238	    /**
239	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
240	     * source of truth for how an email is persisted, so inputs that differ only in letter case
241	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
242	     * (create and update, mapper or hand-copied) stores the same canonical value.
243	     *
244	     * @param email the raw email, possibly {@code null}
245	     * @return the lower-cased form, or {@code null} if the input was {@code null}
246	     */
247	    public static String normalizeEmail(String email) {
248	        return email == null ? null : email.toLowerCase();
249	    }
250	
251	    /**
252	     * Disposable email domains that are not accepted for an owner. Compared case-insensitively
253	     * against the domain part of the owner's email (see {@link #isDisposableEmailDomain(String)}).
254	     */
255	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
256	        "mailinator.com",
257	        "tempmail.com",
258	        "guerrillamail.com");
259	
260	    /**
261	     * Check whether an email's domain is on the disposable-domain blocklist. The domain is the text
262	     * after the last {@code '@'}, compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}.
263	     * This is the single source of truth for which email domains are rejected, shared by any
264	     * persistence path. A {@code null} or empty email, or one with no {@code '@'}, is not disposable.
265	     *
266	     * @param email the owner's email, possibly {@code null}
267	     * @return {@code true} if the email's domain is on the blocklist, {@code false} otherwise
268	     */
269	    public static boolean isDisposableEmailDomain(String email) {
270	        if (email == null) {
271	            return false;
272	        }
273	        int at = email.lastIndexOf('@');
274	        if (at < 0) {
275	            return false;
276	        }
277	        String domain = email.substring(at + 1).toLowerCase();
278	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
279	    }
280	
281	    /**
282	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
283	     * truth for how a telephone is compared and persisted, so inputs that differ only in
284	     * formatting (spaces, dashes, brackets) are treated as the same number.
285	     *
286	     * <p>The rules are:
287	     * <ul>
288	     *   <li>spaces, dashes and brackets are stripped;</li>
289	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
290	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
291	     *       is dropped from the national digits;</li>
292	     *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
293	     *   <li>for a recognized country code the national number (the digits after the country
294	     *       code) must have the length that code requires: {@code '+61'} requires 9 national
295	     *       digits and {@code '+1'} requires 10.</li>
296	     * </ul>
297	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
298	     * values are returned unchanged.
299	     *
300	     * @param telephone the raw telephone, possibly {@code null}
301	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
302	     *     valid E.164 number
303	     */
304	    public static String normalizeTelephone(String telephone) {
305	        if (telephone == null) {
306	            return null;
307	        }
308	        String trimmed = telephone.trim();
309	        boolean hasCountryCode = trimmed.startsWith("+");
310	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
311	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
312	        if (hasCountryCode) {
313	            stripped = stripped.substring(1);
314	        }
315	        if (!stripped.matches("\\d+")) {
316	            return null;
317	        }
318	        String digits;
319	        if (hasCountryCode) {
320	            digits = stripped;
321	        } else {
322	            if (stripped.startsWith("0")) {
323	                stripped = stripped.substring(1);
324	            }
325	            digits = "61" + stripped;
326	        }
327	        if (digits.length() < 8 || digits.length() > 15) {
328	            return null;
329	        }
330	        if (!hasValidNationalNumberLength(digits)) {
331	            return null;
332	        }
333	        return "+" + digits;
334	    }
335	
336	    /**
337	     * Format a stored E.164 telephone for human display: the country code, a space, then the
338	     * national digits grouped left-to-right in blocks of three separated by spaces (e.g.
339	     * {@code "+61412345678"} becomes {@code "+61 412 345 678"}). The country code is identified
340	     * from the recognized {@link #NATIONAL_NUMBER_LENGTHS} table (longest prefix first); when no
341	     * recognized country code matches, the digits after the {@code '+'} are grouped in threes with
342	     * no separate country-code segment. This is a display-only transform; the raw E.164 value is
343	     * kept unchanged elsewhere.
344	     *
345	     * @param telephone the stored E.164 telephone, possibly {@code null}
346	     * @return the human-formatted telephone, or {@code null} when the input is {@code null}; an
347	     *     input that is not a well-formed E.164 number ({@code '+'} followed by digits) is returned
348	     *     unchanged
349	     */
350	    public static String telephoneDisplay(String telephone) {
351	        if (telephone == null) {
352	            return null;
353	        }
354	        if (!telephone.matches("\\+\\d+")) {
355	            return telephone;
356	        }
357	        String digits = telephone.substring(1);
358	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
359	            if (digits.startsWith(countryCode)) {
360	                return "+" + countryCode + " " + groupDigits(digits.substring(countryCode.length()));
361	            }
362	        }
363	        return "+" + groupDigits(digits);
364	    }
365	
366	    /**
367	     * Group a run of digits left-to-right into blocks of three separated by single spaces, with a
368	     * trailing block of one or two digits when the length is not a multiple of three (e.g.
369	     * {@code "412345678"} becomes {@code "412 345 678"}).
370	     *
371	     * @param digits the national digits
372	     * @return the space-grouped digits
373	     */
374	    private static String groupDigits(String digits) {
375	        StringBuilder grouped = new StringBuilder(digits.length() + digits.length() / 3);
376	        for (int i = 0; i < digits.length(); i++) {
377	            if (i > 0 && i % 3 == 0) {
378	                grouped.append(' ');
379	            }
380	            grouped.append(digits.charAt(i));
381	        }
382	        return grouped.toString();
383	    }
384	
385	    /**
386	     * Required national-number length (the count of digits after the country code) for each
387	     * recognized country code, longest country code first so the prefix match is unambiguous.
388	     */
389	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
390	    static {
391	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
392	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
393	    }
394	
395	    /**
396	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
397	     * length its country code requires. A country code with no registered length places no
398	     * additional constraint and is accepted.
399	     *
400	     * @param digits the E.164 digits without the leading {@code '+'}
401	     * @return {@code true} if the national-number length is valid for the country code
402	     */
403	    private static boolean hasValidNationalNumberLength(String digits) {
404	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
405	            String countryCode = entry.getKey();
406	            if (digits.startsWith(countryCode)) {
407	                return digits.length() - countryCode.length() == entry.getValue();
408	            }
409	        }
410	        return true;
411	    }
412	
413	    /**
414	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
415	     * upper-cased abbreviation.
416	     */
417	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
418	        "ST", "STREET",
419	        "RD", "ROAD",
420	        "AVE", "AVENUE");
421	
422	    /**
423	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
424	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
425	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
426	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
427	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
428	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
429	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
430	     * value. The transform is idempotent: a normalized address normalizes to itself.
431	     *
432	     * @param address the raw address, possibly {@code null}
433	     * @return the normalized form, or {@code null} if the input was {@code null}
434	     */
435	    public static String normalizeAddress(String address) {
436	        if (address == null) {
437	            return null;
438	        }
439	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
440	        if (collapsed.isEmpty()) {
441	            return collapsed;
442	        }
443	        String[] tokens = collapsed.split(" ");
444	        StringBuilder normalized = new StringBuilder(collapsed.length());
445	        for (int i = 0; i < tokens.length; i++) {
446	            if (i > 0) {
447	                normalized.append(' ');
448	            }
449	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
450	        }
451	        return normalized.toString();
452	    }
453	
454	    /**
455	     * Compose an owner's canonical {@code address} from the two accepted input forms, preferring the
456	     * structured fields over the flat value. When a non-blank {@code addressLine1} is present the
457	     * result is that line, with a single space and {@code addressLine2} appended when the second line
458	     * is present; otherwise the flat {@code address} value is used. All three arguments are expected
459	     * to already be normalized (see {@link #normalizeAddress(String)}). This is the single source of
460	     * truth for how an owner's address is read, so every consumer (the stored value and the response)
461	     * sees the structured fields when present and the flat value as the backward-compatible fallback.
462	     *
463	     * @param addressLine1 the normalized first structured line, possibly {@code null} or blank
464	     * @param addressLine2 the normalized optional second structured line, possibly {@code null} or blank
465	     * @param flatAddress the normalized flat address, possibly {@code null}
466	     * @return the composed address, or the flat value / {@code null} when no structured line is present
467	     */
468	    public static String composeAddress(String addressLine1, String addressLine2, String flatAddress) {
469	        if (addressLine1 != null && !addressLine1.isBlank()) {
470	            if (addressLine2 != null && !addressLine2.isBlank()) {
471	                return addressLine1 + " " + addressLine2;
472	            }
473	            return addressLine1;
474	        }
475	        return flatAddress;
476	    }
477	
478	    /**
479	     * Check whether an owner supplies a postal address in at least one accepted form: a non-blank
480	     * structured {@code addressLine1}, or a non-blank flat {@code address}. This is the single source
481	     * of truth for the address presence rule, shared by the DTO validation and any persistence path.
482	     *
483	     * @param addressLine1 the structured first line, possibly {@code null}
484	     * @param address the flat address, possibly {@code null}
485	     * @return {@code true} if either form supplies a non-blank value, {@code false} otherwise
486	     */
487	    public static boolean hasAddress(String addressLine1, String address) {
488	        return (addressLine1 != null && !addressLine1.isBlank())
489	            || (address != null && !address.isBlank());
490	    }
491	
492	    /**
493	     * Normalize a household field (such as last name or address) to its canonical form for
494	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
495	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
496	     * that differ only in letter case or spacing are treated as the same value.
497	     *
498	     * @param value the raw field value, possibly {@code null}
499	     * @return the normalized form, or {@code null} if the input was {@code null}
500	     */
501	    public static String normalizeHousehold(String value) {
502	        if (value == null) {
503	            return null;
504	        }
505	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
506	    }
507	
508	    /**
509	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
510	     * last name (compared case-insensitively with collapsed whitespace, see
511	     * {@link #normalizeHousehold(String)}) and the same postcode. The value is deterministic in
512	     * those two fields, so two owners who share a last name and postcode are assigned the same id
513	     * automatically. It is formatted {@code 'HH-<HEX12>'} where {@code HEX12} is the first twelve
514	     * upper-cased hex characters of the SHA-256 digest of
515	     * {@code normalizedLastName + '|' + postcode}.
516	     *
517	     * @param lastName the owner's last name, possibly {@code null}
518	     * @param postcode the owner's postcode, possibly {@code null}
519	     * @return the household id, or {@code null} if either field is {@code null}
520	     */
521	    public static String householdId(String lastName, String postcode) {
522	        String normalizedLastName = normalizeHousehold(lastName);
523	        if (normalizedLastName == null || postcode == null) {
524	            return null;
525	        }
526	        String key = normalizedLastName + "|" + postcode;
527	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase();
528	    }
529	
530	    /**
531	     * Compute the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. This is the
532	     * shared primitive behind every hash-derived owner value (the household id and the customer code),
533	     * so they all agree on algorithm and encoding.
534	     *
535	     * @param value the string to digest, never {@code null}
536	     * @return the 64-character lower-case hex digest
537	     */
538	    private static String sha256Hex(String value) {
539	        try {
540	            byte[] digest = MessageDigest.getInstance("SHA-256")
541	                .digest(value.getBytes(StandardCharsets.UTF_8));
542	            StringBuilder hex = new StringBuilder(digest.length * 2);
543	            for (byte b : digest) {
544	                hex.append(String.format("%02x", b));
545	            }
546	            return hex.toString();
547	        } catch (NoSuchAlgorithmException e) {
548	            // SHA-256 is a standard algorithm required to be present on every JVM.
549	            throw new IllegalStateException("SHA-256 not available", e);
550	        }
551	    }
552	
553	    /**
554	     * Build an owner's {@code customerCode}, the stable owner identity assigned once when the owner is
555	     * created. It is formatted {@code '<REGION>-<HASH8>'} where:
556	     * <ul>
557	     *   <li>{@code REGION} is the region code derived from the postcode (see
558	     *       {@link #regionForPostcode(String)}), or {@code 'UNKNOWN'} when the postcode is absent or
559	     *       in no known range, and</li>
560	     *   <li>{@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the
561	     *       normalized telephone (see {@link #normalizeTelephone(String)}) concatenated with the last
562	     *       name.</li>
563	     * </ul>
564	     * The value is deterministic in the postcode, telephone and last name (e.g.
565	     * {@code 'NSW-1A2B3C4D'}); it carries no sequence number.
566	     *
567	     * @param postcode the owner's postcode, possibly {@code null}
568	     * @param telephone the owner's raw telephone, possibly {@code null}
569	     * @param lastName the owner's last name, possibly {@code null}
570	     * @return the customer code, or {@code null} if the telephone or last name is {@code null}
571	     */
572	    public static String customerCode(String postcode, String telephone, String lastName) {
573	        if (telephone == null || lastName == null) {
574	            return null;
575	        }
576	        String region = regionForPostcode(postcode);
577	        if (region == null) {
578	            region = "UNKNOWN";
579	        }
580	        String normalizedTelephone = normalizeTelephone(telephone);
581	        String key = (normalizedTelephone == null ? "" : normalizedTelephone) + lastName;
582	        return region + "-" + sha256Hex(key).substring(0, 8).toUpperCase();
583	    }
584	
585	    /**
586	     * Compute an owner's {@code identityKey}, the single derived value through which all
587	     * duplicate detection is now expressed. It consolidates the three formerly separate
588	     * telephone, email and household duplicate checks into one key, formatted as
589	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}:
590	     * <ul>
591	     *   <li>the normalized telephone (see {@link #normalizeTelephone(String)}),</li>
592	     *   <li>the normalized email (see {@link #normalizeEmail(String)}), or the empty string
593	     *       when no email is present, and</li>
594	     *   <li>the household id (see {@link #householdId(String, String)}).</li>
595	     * </ul>
596	     * A {@code null} component is rendered as the empty string. Two owners are the same identity
597	     * only when their <em>whole</em> keys are equal; because the telephone is part of the key, two
598	     * members of the same household with different telephones have different keys.
599	     *
600	     * @param telephone the owner's raw telephone, possibly {@code null}
601	     * @param email the owner's email, possibly {@code null}
602	     * @param lastName the owner's last name, possibly {@code null}
603	     * @param postcode the owner's postcode, possibly {@code null}
604	     * @return the identity key, never {@code null}
605	     */
606	    public static String identityKey(String telephone, String email, String lastName, String postcode) {
607	        String normalizedTelephone = normalizeTelephone(telephone);
608	        String normalizedEmail = normalizeEmail(email);
609	        String household = householdId(lastName, postcode);
610	        return (normalizedTelephone == null ? "" : normalizedTelephone)
611	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
612	            + "|" + (household == null ? "" : household);
613	    }
614	
615	    /**
616	     * Build an owner's {@code membershipNumber}, the stable membership identifier derived from the
617	     * owner's own persisted fields. It is formatted {@code '<customerCode>-M<YY>'} where {@code YY}
618	     * is the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). The
619	     * value is deterministic in those two fields.
620	     *
621	     * @param customerCode the owner's customer code, possibly {@code null}
622	     * @param registrationDate the owner's registration date, possibly {@code null}
623	     * @return the membership number, or {@code null} if either field is {@code null}
624	     */
625	    public static String membershipNumber(String customerCode, LocalDate registrationDate) {
626	        if (customerCode == null || registrationDate == null) {
627	            return null;
628	        }
629	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
630	    }
631	
632	    /**
633	     * Compute an owner's {@code membershipPoints}, the derived points score assigned on create. The
634	     * score starts at 0, gains 2 when an email is present, gains 1 when {@code namesakeCount} is 0,
635	     * gains 2 when the owner belongs to a household of 3 or more members (see {@code householdCount}),
636	     * and gains 3 when the owner's tenure is more than 365 days (the tenure being the number of days
637	     * from {@code registrationDate} to today). Because a newly created owner has zero tenure, the
638	     * tenure points accrue only once the owner has been a member for over a year.
639	     *
640	     * @param namesakeCount the owner's namesake count, possibly {@code null}
641	     * @param email the owner's email, possibly {@code null}
642	     * @param householdCount the number of members in the owner's household, possibly {@code null}
643	     * @param registrationDate the owner's registration date, possibly {@code null}
644	     * @return the membership points, a non-negative integer
645	     */
646	    public static int membershipPoints(Integer namesakeCount, String email, Integer householdCount,
647	            LocalDate registrationDate) {
648	        int points = 0;
649	        if (email != null && !email.isEmpty()) {
650	            points += 2;
651	        }
652	        if (namesakeCount != null && namesakeCount == 0) {
653	            points += 1;
654	        }
655	        if (householdCount != null && householdCount >= 3) {
656	            points += 2;
657	        }
658	        if (registrationDate != null
659	            && ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365) {
660	            points += 3;
661	        }
662	        return points;
663	    }
664	
665	    /**
666	     * Map an owner's {@code membershipPoints} to its {@code membershipLevel}: level 1 for 0-1 points,
667	     * level 2 for 2-3, level 3 for 4-5 and level 4 for 6 or more.
668	     *
669	     * @param membershipPoints the owner's membership points
670	     * @return the membership level, an integer from 1 to 4
671	     */
672	    public static int membershipLevel(int membershipPoints) {
673	        if (membershipPoints >= 6) {
674	            return 4;
675	        }
676	        if (membershipPoints >= 4) {
677	            return 3;
678	        }
679	        if (membershipPoints >= 2) {
680	            return 2;
681	        }
682	        return 1;
683	    }
684	
685	    /**
686	     * Fixed city-to-region table used by {@link #regionForCity(String)} to resolve a city's region
687	     * for postcode validation, keyed by the exact city name.
688	     */
689	    private static final Map<String, String> CITY_REGION = Map.of(
690	        "Sydney", "NSW",
691	        "Melbourne", "VIC",
692	        "Brisbane", "QLD");
693	
694	    /**
695	     * Derive an owner's {@code locality}, the canonical region for the owner, from the {@code REGION}
696	     * segment of the owner's {@code customerCode} (see {@link #customerCode(String, String, String)}).
697	     * Because the customer code's region is itself derived from the postcode, the locality now shares
698	     * the owner's region-and-hash identity: it is the text before the first {@code '-'} of the customer
699	     * code. When the owner has no customer code the locality is {@code 'UNKNOWN'}.
700	     *
701	     * @param customerCode the owner's customer code, possibly {@code null}
702	     * @return the canonical region string, or {@code 'UNKNOWN'} when no customer code is present
703	     */
704	    public static String locality(String customerCode) {
705	        if (customerCode == null) {
706	            return "UNKNOWN";
707	        }
708	        int dash = customerCode.indexOf('-');
709	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
710	    }
711	
712	    /**
713	     * Fixed region-to-timezone table used by {@link #timezone(String)} to resolve an owner's IANA
714	     * timezone name from its canonical region ({@code NSW}->{@code Australia/Sydney},
715	     * {@code VIC}->{@code Australia/Melbourne}, {@code QLD}->{@code Australia/Brisbane}). A region
716	     * not in this table (including {@code 'UNKNOWN'}) has no timezone.
717	     */
718	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
719	        "NSW", "Australia/Sydney",
720	        "VIC", "Australia/Melbourne",
721	        "QLD", "Australia/Brisbane");
722	
723	    /**
724	     * Derive an owner's {@code timezone}, the IANA timezone name for the owner's locality/region,
725	     * from the fixed {@link #REGION_TIMEZONE} table ({@code NSW}->{@code Australia/Sydney},
726	     * {@code VIC}->{@code Australia/Melbourne}, {@code QLD}->{@code Australia/Brisbane}). The region
727	     * is the owner's {@code locality} (see {@link #locality(String)}), itself the {@code REGION}
728	     * segment of the customer code. A region not in the table (including {@code 'UNKNOWN'}) has no
729	     * timezone and yields {@code null}.
730	     *
731	     * @param customerCode the owner's customer code, possibly {@code null}
732	     * @return the IANA timezone name, or {@code null} when the owner's region has no mapped timezone
733	     */
734	    public static String timezone(String customerCode) {
735	        return REGION_TIMEZONE.get(locality(customerCode));
736	    }
737	
738	    /**
739	     * Resolve the canonical region for a city from the fixed {@link #CITY_REGION} table. A city not
740	     * in the table (including {@code null}) resolves to {@code 'UNKNOWN'}.
741	     *
742	     * @param city the owner's city, possibly {@code null}
743	     * @return the matching region, or {@code 'UNKNOWN'} when the city is not in the table
744	     */
745	    private static String regionForCity(String city) {
746	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
747	    }
748	
749	    /**
750	     * Fixed region-to-postcode-range table used by {@link #isPostcodeValidForCity(String, String)}
751	     * and {@link #regionForPostcode(String)}, keyed by the canonical region. Each entry is the
752	     * inclusive low and high bound of the region's valid 4-digit postcodes
753	     * ({@code NSW} 2000-2099, {@code VIC} 3000-3099, {@code QLD} 4000-4099). A region not in this
754	     * table (including {@code 'UNKNOWN'}) places no range constraint.
755	     */
756	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
757	        "NSW", new int[] {2000, 2099},
758	        "VIC", new int[] {3000, 3099},
759	        "QLD", new int[] {4000, 4099});
760	
761	    /**
762	     * Resolve the canonical region whose postcode range contains the given postcode, using the fixed
763	     * {@link #REGION_POSTCODE_RANGES} table. A {@code null} postcode, one that is not exactly four
764	     * digits, or one that falls in no known range resolves to {@code null}.
765	     *
766	     * @param postcode the owner's postcode, possibly {@code null}
767	     * @return the matching region, or {@code null} when no range contains the postcode
768	     */
769	    private static String regionForPostcode(String postcode) {
770	        if (postcode == null || !postcode.matches("\\d{4}")) {
771	            return null;
772	        }
773	        int value = Integer.parseInt(postcode);
774	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
775	            int[] range = entry.getValue();
776	            if (value >= range[0] && value <= range[1]) {
777	                return entry.getKey();
778	            }
779	        }
780	        return null;
781	    }
782	
783	    /**
784	     * Check whether a postcode is valid for an owner's city. Postcode is optional, so a
785	     * {@code null} or empty postcode is always valid. When present it must be exactly four
786	     * digits, and when the city's region (from the fixed city-to-region table) has a known postcode
787	     * range the value must fall within that inclusive range. A city with no known region accepts
788	     * any four-digit postcode. This is the single source of
789	     * truth for postcode validity, shared by the DTO validation and any persistence path.
790	     *
791	     * @param postcode the owner's postcode, possibly {@code null}
792	     * @param city the owner's city, possibly {@code null}
793	     * @return {@code true} if the postcode is absent or valid for the city, {@code false} otherwise
794	     */
795	    public static boolean isPostcodeValidForCity(String postcode, String city) {
796	        if (postcode == null || postcode.isEmpty()) {
797	            return true;
798	        }
799	        if (!postcode.matches("\\d{4}")) {
800	            return false;
801	        }
802	        int[] range = REGION_POSTCODE_RANGES.get(regionForCity(city));
803	        if (range == null) {
804	            return true;
805	        }
806	        int value = Integer.parseInt(postcode);
807	        return value >= range[0] && value <= range[1];
808	    }
809	
810	    /**
811	     * Compute an owner's {@code checkDigit}, a single Luhn check digit (0-9) over the digits
812	     * contained in the {@code customerCode}. Non-digit characters in the code are ignored. The
813	     * value is deterministic in the customer code and is the standard Luhn check digit: each
814	     * digit is weighted right-to-left, every second digit (starting with the rightmost) is
815	     * doubled with digit sums above nine reduced by nine, and the check digit is the amount that
816	     * brings the weighted sum up to the next multiple of ten.
817	     *
818	     * @param customerCode the owner's customer code, possibly {@code null}
819	     * @return the Luhn check digit from 0 to 9, or {@code null} if the customer code is {@code null}
820	     */
821	    public static Integer checkDigit(String customerCode) {
822	        if (customerCode == null) {
823	            return null;
824	        }
825	        int sum = 0;
826	        boolean dbl = true;
827	        for (int i = customerCode.length() - 1; i >= 0; i--) {
828	            char c = customerCode.charAt(i);
829	            if (c < '0' || c > '9') {
830	                continue;
831	            }
832	            int d = c - '0';
833	            if (dbl) {
834	                d *= 2;
835	                if (d > 9) {
836	                    d -= 9;
837	                }
838	            }
839	            sum += d;
840	            dbl = !dbl;
841	        }
842	        return (10 - (sum % 10)) % 10;
843	    }
844	
845	    /**
846	     * Derive an owner's {@code contactPreference}, the preferred channel for contacting the owner.
847	     * The value is {@code 'EMAIL'} when an email is present and {@code 'PHONE'} otherwise. The value
848	     * is deterministic in the email.
849	     *
850	     * @param email the owner's email, possibly {@code null}
851	     * @return {@code 'EMAIL'} when an email is present, otherwise {@code 'PHONE'}
852	     */
853	    public static String contactPreference(String email) {
854	        return (email != null && !email.isEmpty()) ? "EMAIL" : "PHONE";
855	    }
856	
857	    /**
858	     * Derive an owner's {@code ageBand}, the band the owner's age falls into on the registration
859	     * date. The age in whole years is the number of completed years between {@code birthDate} and
860	     * {@code registrationDate}, and the band is {@code 'MINOR'} when under 18, {@code 'ADULT'} when
861	     * 18 to 64 inclusive, and {@code 'SENIOR'} when 65 or older. The value is deterministic in those
862	     * two fields and is only defined when both are present.
863	     *
864	     * @param birthDate the owner's date of birth, possibly {@code null}
865	     * @param registrationDate the owner's registration date, possibly {@code null}
866	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when either date
867	     *     is {@code null}
868	     */
869	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
870	        if (birthDate == null || registrationDate == null) {
871	            return null;
872	        }
873	        int age = Period.between(birthDate, registrationDate).getYears();
874	        if (age < 18) {
875	            return "MINOR";
876	        }
877	        if (age < 65) {
878	            return "ADULT";
879	        }
880	        return "SENIOR";
881	    }
882	
883	    protected Set<Pet> getPetsInternal() {
884	        if (this.pets == null) {
885	            this.pets = new HashSet<>();
886	        }
887	        return this.pets;
888	    }
889	
890	    protected void setPetsInternal(Set<Pet> pets) {
891	        this.pets = pets;
892	    }
893	
894	    public List<Pet> getPets() {
895	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
896	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
897	        return Collections.unmodifiableList(sortedPets);
898	    }
899	
900	    public void setPets(List<Pet> pets) {
901	        this.pets = new HashSet<>(pets);
902	    }
903	
904	    public void addPet(Pet pet) {
905	        getPetsInternal().add(pet);
906	        pet.setOwner(this);
907	    }
908	
909	    /**
910	     * Return the Pet with the given name, or null if none found for this Owner.
911	     *
912	     * @param name to test
913	     * @return true if pet name is already in use
914	     */
915	    public Pet getPet(String name) {
916	        return getPet(name, false);
917	    }
918	
919	    /**
920	     * Return the Pet with the given name, or null if none found for this Owner.
921	     *
922	     * @param name to test
923	     * @return true if pet name is already in use
924	     */
925	    public Pet getPet(String name, boolean ignoreNew) {
926	        name = name.toLowerCase();
927	        for (Pet pet : getPetsInternal()) {
928	            if (!ignoreNew || !pet.isNew()) {
929	                String compName = pet.getName();
930	                compName = compName.toLowerCase();
931	                if (compName.equals(name)) {
932	                    return pet;
933	                }
934	            }
935	        }
936	        return null;
937	    }
938	
939	    public Pet getPet(Integer petId) {
940	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
941	    }
942	
943	    @Override
944	    public String toString() {
945	        return new ToStringCreator(this)
946	
947	            .append("id", this.getId())
948	            .append("new", this.isNew())
949	            .append("lastName", this.getLastName())
950	            .append("firstName", this.getFirstName())
951	            .append("address", this.address)
952	            .append("city", this.city)
953	            .append("telephone", this.telephone)
954	            .toString();
955	    }
956	}
